# ``linear_attn_config`` / ``rope_parameters`` are indexed as mappings by ``provider_bridge``,
# so they must stay ``dict`` while the rest of the tree becomes ``SimpleNamespace``.
_DICT_VALUED_FIELDS = frozenset({"linear_attn_config", "rope_parameters", "rope_scaling"})

# Physical layers are addressed as ``decoder.layers.<N>`` and MTP inner layers as
# ``mtp.layers.<M>.mtp_model_layer.layers.<N>``; both gain the mHC wrapper's ``inner_layer.``.
_PHYSICAL_LAYER = re.compile(r"^(language_model\.decoder\.layers\.\d+)\.(.*)$")
_MTP_INNER_LAYER = re.compile(r"^(language_model\.mtp\.layers\.\d+\.mtp_model_layer\.layers\.\d+)\.(.*)$")
# mHC mode splits the fused ``eh_proj`` into ``e_proj`` (embedding half) and ``h_proj``
# (hidden half); the registry maps both halves of the single HF ``eh_proj.weight``.
_MTP_FUSED_EH_PROJ = re.compile(r"^(language_model\.mtp\.layers\.\d+)\.eh_proj\.weight$")


def _namespace(mapping: dict) -> SimpleNamespace:
    """Convert a config mapping to ``SimpleNamespace``, keeping indexed sub-mappings as dicts."""
    return SimpleNamespace(
        **{
            key: value if key in _DICT_VALUED_FIELDS or not isinstance(value, dict) else _namespace(value)
            for key, value in mapping.items()
        }
    )


def _hf_config() -> SimpleNamespace:
    config = _namespace(_TEXT_CONFIG)
    config.text_config = config
    return config


def _provider() -> GLM53FlashModelProvider:
    bridge = GLM53FlashBridge()
    bridge.hf_config = _hf_config()
    return bridge.provider_bridge(SimpleNamespace(config=bridge.hf_config))


def _module_tree_names(observed: list, *, hyper_connections: bool) -> list:
    """Return the Megatron parameter names MCore builds for ``observed`` checkpoint tensors.

    ``observed`` is the parameter list of a run whose configuration left the mHC wrapper
    disabled, so ``hyper_connections=True`` re-derives the names of the wrapped tree the
    bridge's registry is written for.
    """
    names = []
    for name in observed:
        if not hyper_connections:
            names.append(name)
            continue
        match = _PHYSICAL_LAYER.match(name) or _MTP_INNER_LAYER.match(name)
        if match:
            names.append(f"{match.group(1)}.inner_layer.{match.group(2)}")
            continue
        match = _MTP_FUSED_EH_PROJ.match(name)
        if match:
            names.extend((f"{match.group(1)}.e_proj.weight", f"{match.group(1)}.h_proj.weight"))
            continue
        names.append(name)
    return names


def test_provider_bridge_enables_the_hyper_connection_module_tree():
    """``provider_bridge`` must set the mHC switch under the name Megatron-Core reads.

    An unknown attribute on the provider dataclass is silently accepted and never reaches
    the ``TransformerConfig``, which is how the wrapped tree went missing.
    """
    provider = _provider()
    assert "enable_hyper_connections" in GLM53FlashModelProvider.__dataclass_fields__
    assert provider.enable_hyper_connections is True, (
        "provider_bridge left enable_hyper_connections unset; the HyperConnectionHybridLayer "
        "wrapper (and therefore every inner_layer. registry path) will not exist"
    )
    assert provider.num_residual_streams == _TEXT_CONFIG["hc_mult"]


def test_registry_covers_every_parameter_of_every_layer_in_the_configured_module_tree():
    """All 3909 parameters the failing run reported must resolve to a concrete HF tensor."""
    provider = _provider()
    bridge = GLM53FlashBridge()
    bridge.hf_config = _hf_config()
    registry = bridge.mapping_registry()

    assert len(_OBSERVED_UNMAPPED_PARAMETERS) == 3909
    names = _module_tree_names(_OBSERVED_UNMAPPED_PARAMETERS, hyper_connections=provider.enable_hyper_connections)
    unmapped = [
        name for name in names if registry.megatron_to_hf_lookup(bridge._get_lora_unwrapped_name(name)) is None
    ]
    assert not unmapped, (
        f"{len(unmapped)} of {len(names)} Megatron parameters have no HF mapping after the "
        f"model was configured with enable_hyper_connections={provider.enable_hyper_connections}:\n  "
        + "\n  ".join(unmapped[:20])
    )


